	@Inject
	public MazeCompGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pMazeFile = new MazeFileElements();
		this.pEString = new EStringElements();
		this.pEBoolean = new EBooleanElements();
		this.pEInt = new EIntElements();
		this.pEDouble = new EDoubleElements();
		this.eBehaviorType = new BehaviorTypeElements();
		this.pZombie = new ZombieElements();
		this.pGhost = new GhostElements();
		this.pPumpkinBomber = new PumpkinBomberElements();
		this.pLootTable = new LootTableElements();
		this.pLootItem = new LootItemElements();
		this.eLootItemType = new LootItemTypeElements();
		this.eProjectileType = new ProjectileTypeElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("main.game.maze.MazeComp".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
